typedef struct {
    tls_ctx_t ctx;
    char host[128];
    char port[8];
    bool in_use; /* locked by a request */
    bool valid; /* connection is alive */
    pid_t owner; /* 归属的 task group；0 = 从未被占用过 */
} conn_slot_t;

static conn_slot_t s_pool[CONN_POOL_SIZE];
static pthread_mutex_t s_pool_lock = PTHREAD_MUTEX_INITIALIZER;

/* 当前线程所属 task group 的编号，用作槽位的 owner。
 *
 * NuttX 下 getpid() 返回的是 **task group 的 pid**（libs/libc/sched/task_getpid.c
 * 返回 group 的 tg_info->ta_pid，而 group_create 里 ta_pid = tg_pid）；pthread_create
 * 出来的线程走 group_bind() 直接继承创建者的 group，不会新建 group，所以：
 *   - 同一个 task group 里的所有线程（含 pthread）getpid() 完全一样；
 *   - hello_app / robot_ui / ai_agent 这三个 app 是三个独立 task group，彼此不同。
 * 这正是"fd 属于哪个组"的判据 —— fd 表就挂在 group 上。 */
static pid_t pool_owner(void)
{
    return getpid();
}

/* Acquire a slot for host:port.  Returns a locked, connected ctx or NULL. */
static conn_slot_t* pool_acquire(const char* host, const char* port)
{
    /* ★ 为什么槽位必须按 task group（owner）隔离 —— 裸 fd 不能跨组用
     *
     * 槽位里存的是一个**裸 fd 号**（藏在 ctx.net.fd），而 NuttX 的 fd 号只在 task
     * group 内有意义（每个 group 的 fd 各自从 3 开始编号），整机又是单一大镜像
     * （本文件这些 static 对象、池子，全机只有一份）。于是"A 组的代码拿到 B 组的

     * （本文件这些 static 对象、池子，全机只有一份）。于是"A 组的代码拿到 B 组的
     * 槽位"就等于拿着一个只在 B 组里有意义的 fd 号在 A 组里用，两种坏结果：
     *   ① 该号在 A 组不存在 → close() 报 EBADF、没人注意，对端的 keep-alive 永远
     *      不回收；
     *   ② 该号在 A 组恰好被别的活跃文件占着（MQTT/push socket、音频设备、lcd…
     *      全都从 3 开始编）→ **误关了别人的 fd**；紧接着 A 组下一次 socket() 极可能
     *      又拿回同一个号，别的持有者（比如每 100ms recv 一次的那个 network 任务）
     *      继续用这个号收发，就和这条 TLS 连接**共享了同一个 socket** → mbedtls 读
     *      到的是别人的协议字节流 → ssl_handshake ret=-0x7200（INVALID_RECORD）。
     *      2026-09-14 20:10 真机那次"提醒人声丢播报"就是这个错误：hello_app 的
     *      mimo_post() 调 vela_tls_pool_cleanup()，把 ai_agent 组（另一个 task group）
     *      的池子连同 fd 一起在 hello_app 的组里关掉了。
     * 同类教训工程里已经记过一次：app/robot_ui/network_comm.c 写着"跨任务 close() 会
     * 和 network_task 里的 recv() 抢同一个 fd（关掉后 fd 号立刻被复用），实测会把
     * 整机打复位"。
     *
     * 由此定下两条**不要简化回去**的规则：
     *   ① 只有 owner == 本组 的槽位才能复用（别人的 fd 绝不借来用）；
     *   ② **绝不 evict 别人的槽位** —— 那等于 tls_ctx_free() 在别人的组里 close 别人的
     *      fd，正是上面那个事故。池子被别的组占满时宁可返回 NULL，让调用者走临时连接
     *      （功能一样，只是多一次握手）。
     */
    pid_t me = pool_owner();

    pthread_mutex_lock(&s_pool_lock);

    /* 1. Find an existing valid slot for this host:port owned by us */
    for (int i = 0; i < CONN_POOL_SIZE; i++) {
        conn_slot_t* s = &s_pool[i];
        if (s->valid && !s->in_use && s->owner == me && strcmp(s->host, host) == 0 && strcmp(s->port, port) == 0) {
            s->in_use = true;
            pthread_mutex_unlock(&s_pool_lock);
            return s;
        }
    }

    /* 2. Find a slot that holds no live fd (valid==false 时 ctx 一定已经 free 过，
     *    fd 早关了)，就认领它 —— 这种槽位换主人是安全的。 */
    for (int i = 0; i < CONN_POOL_SIZE; i++) {
        if (!s_pool[i].valid && !s_pool[i].in_use) {
            s_pool[i].owner = me;
            s_pool[i].in_use = true;
            pthread_mutex_unlock(&s_pool_lock);
            return &s_pool[i];
        }
    }

    /* 3. Evict one of **our own** idle slots（别人的槽位一个都不许动，见上面 ②） */
    for (int i = 0; i < CONN_POOL_SIZE; i++) {
        if (!s_pool[i].in_use && s_pool[i].owner == me) {
            tls_ctx_free(&s_pool[i].ctx);
            s_pool[i].valid = false;
            s_pool[i].in_use = true;
            pthread_mutex_unlock(&s_pool_lock);
            return &s_pool[i];
        }
    }

    /* 剩下的全是别的组的槽位（或者都在用）：返回 NULL，调用者用临时连接。
     * 池子默认只有 2 个槽位，本组的请求量远小于"被别的组占满"的概率。 */
    pthread_mutex_unlock(&s_pool_lock);
    return NULL; /* all slots busy or owned elsewhere — caller falls back to ephemeral */
}

/* Return a slot to the pool.  keep=true means the connection is still alive. */
static void pool_release(conn_slot_t* s, const char* host, const char* port, bool keep)
{
    /* owner 不在这里改：能走到 pool_release 的槽位一定是本组 pool_acquire 拿到的，
     * 归属本来就对。（keep=false 时 ctx 已经 free、valid=false，这时槽位算"空的"，
     * 别的组可以按 pool_acquire 第 2 步认领它。） */
    pthread_mutex_lock(&s_pool_lock);
    if (keep) {
        strncpy(s->host, host, sizeof(s->host) - 1);
        strncpy(s->port, port, sizeof(s->port) - 1);
        s->valid = true;
    } else {
        tls_ctx_free(&s->ctx);
        s->valid = false;
        s->host[0] = '\0';
    }
    s->in_use = false;
    pthread_mutex_unlock(&s_pool_lock);
}

void vela_tls_pool_cleanup(void)
{
    pid_t me = pool_owner();

    pthread_mutex_lock(&s_pool_lock);
    for (int i = 0; i < CONN_POOL_SIZE; i++) {
        /* ★ 只清自己 task group 的槽位。
         *
         * 这个函数现在被 mimo_post()/weather_http_get() 之类**每次请求前**调用
         * （本意是"把旧连接扔掉、强制全新握手"，见 app/hello_app/mimo_voice.c），
         * 而它跑在调用者自己的 task group 里。槽位里的 fd 号只在本组有意义，
         * 顺手清别人的槽位就是 tls_ctx_free() → 在调用者的组里 close 别人的 fd：
         * 要么静默 EBADF，要么误关本组另一个活文件，然后 fd 号被复用 →
         * ssl_handshake -0x7200（细节见 pool_acquire 头上的长注释）。
         * 别的组的槽位留给它们自己的主人（它们自己也会调这个函数）。 */
        if (s_pool[i].owner != me) {
            continue;
        }
        if (s_pool[i].in_use) {
            syslog(LOG_WARNING,
                "[vela_tls] Pool slot %d still in use, skipping\n", i);
            continue;
        }
        if (s_pool[i].valid) {
            tls_ctx_free(&s_pool[i].ctx);
            s_pool[i].valid = false;
        }
        s_pool[i].host[0] = '\0';
    }
    pthread_mutex_unlock(&s_pool_lock);
}

