static void sf32lb52_audio_tx_wait_timeout(wdparm_t arg)
{
  FAR struct sf32lb52_audio_s *priv = (FAR struct sf32lb52_audio_s *)arg;

  priv->wr_wait_to = true;

  nxsem_post(&priv->wr_sem);
}

