  return NULL;
}

static int asr_race_recognize(const int16_t *pcm, size_t frames,
                              char *out, size_t out_cap)
{
  asr_race_t *r;
  int16_t    *copy;
  pthread_attr_t attr;
  pthread_t  th;
  int        winner = 0;
  int        waited = 0;
  int        free_now = 0;

  if (pcm == NULL || frames == 0 || out == NULL || out_cap == 0)
    {
      return -EINVAL;
    }

  r = calloc(1, sizeof(*r));
  copy = malloc(frames * sizeof(int16_t));
  if (r == NULL || copy == NULL)
    {
      free(r);
      free(copy);
      return -ENOMEM;
    }

  memcpy(copy, pcm, frames * sizeof(int16_t));
  r->pcm = copy;
  r->frames = frames;
  r->refs = 1;                 /* worker 自己 */
  r->threads_left = 0;

  if (sem_init(&r->lock, 0, 1) != 0)
    {
      free(copy);
      free(r);
      return -ENOMEM;
    }

  pthread_attr_init(&attr);
  pthread_attr_setstacksize(&attr, 32768);
  pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_DETACHED);

  /* 先 MiMo，后火山；两个都先登记引用，线程失败再回退。 */
  asr_race_lock(r);
  __atomic_add_fetch(&r->refs, 2, __ATOMIC_ACQ_REL);
  asr_race_unlock(r);

  asr_race_lock(r);
  r->threads_left++;
  asr_race_unlock(r);
  if (pthread_create(&th, &attr, asr_race_mimo, r) != 0)
    {
      asr_race_lock(r);
      r->threads_left--;
      if (r->threads_left <= 0) r->finished = 1;
      asr_race_unlock(r);
      __atomic_sub_fetch(&r->refs, 1, __ATOMIC_ACQ_REL);
    }

  asr_race_lock(r);
  r->threads_left++;
  asr_race_unlock(r);
  if (pthread_create(&th, &attr, asr_race_volc, r) != 0)
    {
      asr_race_lock(r);
      r->threads_left--;
      if (r->threads_left <= 0) r->finished = 1;
      asr_race_unlock(r);
      __atomic_sub_fetch(&r->refs, 1, __ATOMIC_ACQ_REL);
    }

  pthread_attr_destroy(&attr);

  while (waited < ASR_RACE_TIMEOUT_MS)
    {
      asr_race_lock(r);
      winner = r->winner;
      int fin = r->finished;
      asr_race_unlock(r);

      if (winner != 0 || fin)
        {
          break;
        }

      usleep(10000);
      waited += 10;
    }

  asr_race_lock(r);
  winner = r->winner;
  if (winner != 0)
    {
      strncpy(out, r->text, out_cap - 1);
      out[out_cap - 1] = '\0';
    }

  if (__atomic_sub_fetch(&r->refs, 1, __ATOMIC_ACQ_REL) == 0)
    {
      r->finished = 1;
      free_now = 1;
    }
  asr_race_unlock(r);

  if (free_now)
    {
      sem_destroy(&r->lock);
      free((void *)r->pcm);
      free(r);
    }

  return (winner != 0) ? 0 : -ENODATA;
}

