 *   阈值 96 字节（约 32 个汉字）：短回复不弹面板，免得打扰。 */

if (response != NULL && strlen(response) > 96)
  {
    robot_ui_bridge_voice_panel_open();
  }

g_tts_shown[consumed] = '\0';
robot_ui_bridge_voice_reply(g_tts_shown);

