prompt_ack_stop(&g_audio_ctx);

ret = audio_play_start_ref(&g_audio_ctx,
                           (const int16_t *)g_tts_pcm[0],
                           chunk_len / sizeof(int16_t),
                           llm_speak_chunk_complete, ctx);
if (ret < 0)
  {
    printf("[TTS] 首句播放失败: %d\n", ret);
